from typing import List

class Solution:
    def minUnlockedIndices(self, nums: List[int], locked: List[int]) -> int:
        n = len(nums)
        first2 = first3 = n
        last1 = last2 = -1

        for i, val in enumerate(nums):
            if val == 1:
                last1 = i
            elif val == 2:
                if first2 == n:
                    first2 = i
                last2 = i
            else:  # val == 3
                if first3 == n:
                    first3 = i

        # A 3 before a 1 can never be fixed
        if first3 < last1:
            return -1

        count = 0
        for i in range(n):
            if locked[i] == 1 and (first2 <= i < last1 or first3 <= i < last2):
                count += 1
        return count
